/**
 * NetSage AI — Presentation UI  (TASK-014 Polish Pass)
 * dashboard/app.js
 *
 * READ-ONLY presentation layer.
 * All data comes from window.NETSAGE_DATA (generated by build_data_bridge.py).
 * No Gemini calls · No pipeline execution · No data modification.
 */

'use strict';

/* ── Guard ─────────────────────────────────────────────────────────────── */
if (typeof window.NETSAGE_DATA === 'undefined') {
  document.body.innerHTML = `
    <div style="display:flex;align-items:center;justify-content:center;height:100vh;
                flex-direction:column;gap:16px;color:#f87171;font-family:system-ui;padding:20px">
      <div style="font-size:36px">⚠️</div>
      <h2 style="font-size:18px">data.js not found</h2>
      <p style="color:#828fa8;max-width:420px;text-align:center;line-height:1.6;font-size:13px">
        Run <code style="background:#141826;padding:3px 8px;border-radius:4px;color:#9aaad4">
        python dashboard/build_data_bridge.py</code> from the project root, then reload this page.
      </p>
    </div>`;
  throw new Error('NETSAGE_DATA not loaded — run build_data_bridge.py first');
}

const D = window.NETSAGE_DATA;

/* ── Global State ──────────────────────────────────────────────────────── */
let selectedCaseId = null;      // single source of truth for selected case
let filteredCaseIds = D.cases.map(c => c.case_id);
let activeView = 'overview';

/* ── Helpers ───────────────────────────────────────────────────────────── */
const $ = id => document.getElementById(id);

function esc(s) {
  return String(s ?? '—')
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function decisionBadge(d) {
  const cls = (d || '').toLowerCase();
  if (!cls) return '<span class="badge ok">—</span>';
  return `<span class="badge ${cls}">${esc(d)}</span>`;
}

function sevBadge(s) {
  const cls = (s || 'low').toLowerCase();
  return `<span class="badge ${cls}">${esc(s)}</span>`;
}

function pct(v) {
  return typeof v === 'number' ? Math.round(v * 100) + '%' : '—';
}

function getCaseById(id) { return D.cases.find(c => c.case_id === id) || null; }
function getRulesById(id) { return D.ruleResults[id] || []; }
function getDiagById(id) { return D.diagnoses[id] || null; }
function getReviewById(id) { return D.reviewLog.find(r => r.case_id === id) || null; }

/* build review decision lookup once */
function buildReviewMap() {
  const m = {};
  D.reviewLog.forEach(r => { m[r.case_id] = r.decision; });
  return m;
}

/* ── Navigation ─────────────────────────────────────────────────────────── */
function showView(name) {
  if (activeView === name && name !== 'explorer') return;   // skip re-render except explorer
  activeView = name;

  /* hide all views */
  document.querySelectorAll('.view').forEach(v => v.classList.remove('active'));

  /* deactivate all nav items (sidebar + mobile) */
  document.querySelectorAll('.nav-item, .mobile-nav-btn').forEach(n => n.classList.remove('active'));

  /* activate the target view */
  const v = $(`view-${name}`);
  if (v) {
    v.classList.add('active');
    v.scrollTop = 0;          /* reset scroll position */
  }

  /* activate the matching nav buttons */
  const sideNav = $(`nav-${name}`);
  if (sideNav) sideNav.classList.add('active');
  const mobileNav = $(`m-nav-${name}`);
  if (mobileNav) mobileNav.classList.add('active');

  /* Resize charts when switching to overview */
  if (name === 'overview') {
    requestAnimationFrame(resizeCharts);
  }
}

/* Quick demo: navigate to Case Explorer and select C-001 */
function loadDemo() {
  showView('explorer');
  selectCase('C-001');
  setTimeout(() => {
    const el = document.querySelector('.case-item.active');
    if (el) el.scrollIntoView({ block: 'nearest' });
  }, 80);
}

/* ── Tab switching ──────────────────────────────────────────────────────── */
function showTab(name) {
  document.querySelectorAll('.tab-btn').forEach(b => b.classList.remove('active'));
  document.querySelectorAll('.tab-content').forEach(c => c.classList.remove('active'));
  const btn = $(`tab-${name}`);
  const content = $(`content-${name}`);
  if (btn) btn.classList.add('active');
  if (content) content.classList.add('active');
}

/* ══════════════════════════════════════════════════════════════════════════
   VIEW 1 — OVERVIEW
══════════════════════════════════════════════════════════════════════════ */
function renderOverview() {
  const dash = D.dashboard;
  const accepted = dash.review_decisions?.Accepted ?? 0;
  const edited = dash.review_decisions?.Edited ?? 0;
  const rejected = dash.review_decisions?.Rejected ?? 0;

  /* Metric cards */
  $('metric-grid').innerHTML = `
    <div class="metric-card">
      <div class="metric-label">Total Cases</div>
      <div class="metric-value accent">${dash.total_cases}</div>
      <div class="metric-sub">Labelled fault scenarios</div>
    </div>
    <div class="metric-card">
      <div class="metric-label">AI Accepted</div>
      <div class="metric-value green">${accepted}</div>
      <div class="metric-sub">No correction needed</div>
    </div>
    <div class="metric-card">
      <div class="metric-label">Edited</div>
      <div class="metric-value amber">${edited}</div>
      <div class="metric-sub">Reviewer corrected fields</div>
    </div>
    <div class="metric-card">
      <div class="metric-label">Rejected</div>
      <div class="metric-value red">${rejected}</div>
      <div class="metric-sub">Diagnosis substantially wrong</div>
    </div>
    <div class="metric-card">
      <div class="metric-label">Agreement Rate</div>
      <div class="metric-value accent">${pct(dash.agreement_rate)}</div>
      <div class="metric-sub">AI accepted without edit</div>
    </div>
    <div class="metric-card">
      <div class="metric-label">Correction Rate</div>
      <div class="metric-value amber">${pct(dash.correction_rate)}</div>
      <div class="metric-sub">Required human correction</div>
    </div>`;

  /* Charts */
  renderBarChart('chart-categories', dash.issue_type_distribution,
    ['#4f7ef8', '#6588f9', '#7c9ffc', '#93b1fd', '#a8c3fe', '#bcd4ff', '#cde2ff', '#deedff']);
  renderPieChart('chart-decisions', dash.review_decisions,
    ['#4ade80', '#fbbf24', '#f87171']);
  renderBarChart('chart-severity', dash.severity_distribution,
    ['#f87171', '#fbbf24', '#4ade80']);

  /* Rule count table */
  const rc = dash.rule_finding_counts || {};
  const ruleRows = Object.entries(rc)
    .sort((a, b) => b[1] - a[1])
    .map(([name, count]) => `
      <tr>
        <td>${esc(name)}</td>
        <td>${count > 0
        ? `<span class="badge triggered">⚠ ${count} triggered</span>`
        : `<span class="badge ok">✓ 0</span>`}</td>
        <td>${count > 0 ? `Triggered in ${count} of ${dash.total_cases} cases` : 'Not triggered in any case'}</td>
      </tr>`).join('');
  $('rule-count-table').innerHTML = `
    <thead><tr><th>Rule function</th><th>Count</th><th>Note</th></tr></thead>
    <tbody>${ruleRows || '<tr><td colspan="3" style="color:var(--text-muted)">No rule data available.</td></tr>'}</tbody>`;
}

/* ── SVG bar chart with ResizeObserver ──────────────────────────────────── */
const _chartRegistry = {};  // svgId → { data, colours, type }

function renderBarChart(svgId, data, colours) {
  _chartRegistry[svgId] = { data, colours, type: 'bar' };
  _doRenderBar(svgId, data, colours);
}

function _doRenderBar(svgId, data, colours) {
  const svg = $(svgId);
  if (!svg || !data) return;
  const entries = Object.entries(data);
  if (!entries.length) return;

  const parent = svg.parentElement;
  const W = (parent ? parent.clientWidth - 36 : 0) || 340;
  const H = parseInt(svg.getAttribute('height')) || 200;
  const padL = 8, padR = 8, padT = 18, padB = 36;
  const innerW = W - padL - padR;
  const innerH = H - padT - padB;
  const maxVal = Math.max(...entries.map(e => e[1])) || 1;
  const gap = 4;
  const barW = Math.max(Math.floor(innerW / entries.length) - gap, 6);

  const bars = entries.map(([label, val], i) => {
    const bH = Math.max(Math.round((val / maxVal) * innerH), val > 0 ? 2 : 0);
    const x = padL + i * (barW + gap);
    const y = padT + innerH - bH;
    const col = colours[i % colours.length];
    const truncLabel = label.length > 10 ? label.slice(0, 9) + '…' : label;
    return `
      <rect x="${x}" y="${y}" width="${barW}" height="${bH}" rx="3" fill="${col}" opacity="0.9"/>
      <text x="${x + barW / 2}" y="${y - 4}" text-anchor="middle" class="bar-value">${val}</text>
      <text x="${x + barW / 2}" y="${H - padB + 14}" text-anchor="middle" class="bar-label">${esc(truncLabel)}</text>`;
  }).join('');

  svg.setAttribute('viewBox', `0 0 ${W} ${H}`);
  svg.innerHTML = bars;
}

/* ── SVG pie chart ──────────────────────────────────────────────────────── */
function renderPieChart(svgId, data, colours) {
  _chartRegistry[svgId] = { data, colours, type: 'pie' };
  _doRenderPie(svgId, data, colours);
}

function _doRenderPie(svgId, data, colours) {
  const svg = $(svgId);
  if (!svg || !data) return;
  const entries = Object.entries(data);
  const total = entries.reduce((s, e) => s + e[1], 0);
  if (!total) return;

  const parent = svg.parentElement;
  const W = (parent ? parent.clientWidth - 36 : 0) || 300;
  const H = parseInt(svg.getAttribute('height')) || 200;
  const cx = W * 0.36, cy = H / 2, r = Math.min(cx, cy) - 16;

  let paths = '', legendItems = '';
  let angle = -Math.PI / 2;

  entries.forEach(([label, val], i) => {
    const slice = (val / total) * 2 * Math.PI;
    const x1 = cx + r * Math.cos(angle);
    const y1 = cy + r * Math.sin(angle);
    const x2 = cx + r * Math.cos(angle + slice);
    const y2 = cy + r * Math.sin(angle + slice);
    const large = slice > Math.PI ? 1 : 0;
    const col = colours[i % colours.length];
    paths += `<path d="M${cx},${cy} L${x1},${y1} A${r},${r} 0 ${large},1 ${x2},${y2} Z"
              fill="${col}" opacity="0.9" stroke="var(--bg-base)" stroke-width="1.5"/>`;
    const legendY = 28 + i * 26;
    legendItems += `
      <rect x="${W * 0.70}" y="${legendY - 8}" width="10" height="10" rx="2" fill="${col}" opacity="0.9"/>
      <text x="${W * 0.70 + 15}" y="${legendY}" class="pie-label">
        ${esc(label)}: ${val} (${Math.round(val / total * 100)}%)
      </text>`;
    angle += slice;
  });

  svg.setAttribute('viewBox', `0 0 ${W} ${H}`);
  svg.innerHTML = paths + legendItems;
}

/* Re-render all registered charts (called on resize / view switch) */
function resizeCharts() {
  Object.entries(_chartRegistry).forEach(([id, { data, colours, type }]) => {
    if (type === 'bar') _doRenderBar(id, data, colours);
    else _doRenderPie(id, data, colours);
  });
}

/* ══════════════════════════════════════════════════════════════════════════
   VIEW 2 — CASE EXPLORER
══════════════════════════════════════════════════════════════════════════ */
function renderCaseList() {
  /* Populate category dropdown */
  const cats = [...new Set(D.cases.map(c => c.category))].sort();
  $('filter-category').innerHTML = '<option value="">All Categories</option>' +
    cats.map(c => `<option value="${esc(c)}">${esc(c)}</option>`).join('');

  /* Populate severity dropdown */
  const sevs = [...new Set(D.cases.map(c => c.severity).filter(Boolean))].sort();
  $('filter-severity').innerHTML = '<option value="">All Severities</option>' +
    sevs.map(s => `<option value="${esc(s)}">${esc(s)}</option>`).join('');

  filterCases();
}

function filterCases() {
  const q = ($('case-search').value || '').toLowerCase().trim();
  const cat = $('filter-category').value;
  const dec = $('filter-decision').value;
  const sev = $('filter-severity').value;

  const reviewMap = buildReviewMap();

  filteredCaseIds = D.cases
    .filter(c => {
      if (cat && c.category !== cat) return false;
      if (sev && c.severity !== sev) return false;
      if (dec && reviewMap[c.case_id] !== dec) return false;
      if (q) {
        const hay = [c.case_id, c.title, c.category, c.symptom, c.concept, c.severity,
        c.topology_note, c.expected_fault]
          .join(' ').toLowerCase();
        if (!hay.includes(q)) return false;
      }
      return true;
    })
    .map(c => c.case_id);

  $('case-count').textContent = `${filteredCaseIds.length} of ${D.cases.length} cases`;

  const list = $('case-list');
  if (!filteredCaseIds.length) {
    list.innerHTML = `<div class="no-results">No cases match your filters.</div>`;
    return;
  }

  list.innerHTML = filteredCaseIds.map(id => {
    const c = getCaseById(id);
    const decision = reviewMap[id] || '';
    const decClass = decision.toLowerCase();
    const isActive = id === selectedCaseId ? 'active' : '';
    return `
      <div class="case-item ${isActive}" id="ci-${id}"
           onclick="selectCase('${id}')" role="button" tabindex="0"
           onkeydown="if(event.key==='Enter')selectCase('${id}')">
        <span class="case-id">${esc(id)}</span>
        <div class="case-info">
          <div class="case-title-sm">${esc(c.title)}</div>
          <div class="case-cat">${esc(c.category)} · ${esc(c.severity)}</div>
        </div>
        ${decision ? `<span class="badge ${decClass}" style="font-size:9px;padding:2px 6px">${esc(decision)}</span>` : ''}
      </div>`;
  }).join('');
}

function selectCase(id) {
  /* Safety: clear old state to prevent stale data leak */
  const prev = selectedCaseId;
  selectedCaseId = id;

  /* Update list highlight — handle both list panels */
  document.querySelectorAll('.case-item').forEach(el => el.classList.remove('active'));
  const item = $(`ci-${id}`);
  if (item) item.classList.add('active');

  /* Show tab panel, hide empty state */
  const emptyState = $('empty-state');
  const caseTabs = $('case-tabs');
  if (emptyState) emptyState.style.display = 'none';
  if (caseTabs) caseTabs.style.display = '';

  const c = getCaseById(id);
  const rules = getRulesById(id);
  const diag = getDiagById(id);
  const review = getReviewById(id);

  if (!c) {
    if (emptyState) emptyState.style.display = '';
    if (caseTabs) caseTabs.style.display = 'none';
    return;
  }

  renderCaseInfo(c, review);
  renderEvidence(c);
  renderRuleFindings(rules);
  renderDiagnosis(diag, id);
  renderReviewTab(review);

  showTab('info');

  /* Update "selected case" banner if on Human Review page */
  updateReviewSelectedBanner();
}

