/* ── Tab: Evidence ───────────────────────────────────────────────────────── */
function renderEvidence(c) {
  const block = $('evidence-block');
  if (!c.show_outputs || c.show_outputs.trim() === '') {
    block.textContent = '(No show-command output recorded for this case)';
    return;
  }
  block.textContent = c.show_outputs;
}

/* ── Tab: Rule Findings ──────────────────────────────────────────────────── */
function renderRuleFindings(rules) {
  const tbody = $('rule-findings-body');
  if (!rules || !rules.length) {
    tbody.innerHTML = `<tr><td colspan="3" style="color:var(--text-muted);padding:14px 10px">
      No rule results available for this case.</td></tr>`;
    return;
  }
  tbody.innerHTML = rules.map(r => {
    const badge = r.triggered
      ? '<span class="badge triggered">⚠ Triggered</span>'
      : '<span class="badge ok">✓ Not triggered</span>';
    const detail = (r.detail && r.detail.trim() && r.detail !== 'null')
      ? esc(r.detail)
      : (r.triggered ? 'Rule condition met' : 'Rule condition not met');
    return `
      <tr>
        <td>${esc(r.rule_name)}</td>
        <td style="white-space:nowrap">${badge}</td>
        <td>${detail}</td>
      </tr>`;
  }).join('');
}

/* ── Tab: AI Diagnosis ───────────────────────────────────────────────────── */
function renderDiagnosis(diag, caseId) {
  const el = $('diagnosis-content');

  if (!diag) {
    el.innerHTML = `<div class="empty-state">
      <div class="empty-icon">🤖</div>
      <h3>No diagnosis data</h3>
      <p>No entry found in <code>diagnoses.json</code> for ${esc(caseId)}.</p>
    </div>`;
    return;
  }

  if (diag.status === 'needs_manual_review') {
    el.innerHTML = `
      <div class="review-card" style="border-color:var(--edited-border)">
        <div class="field-label" style="color:var(--edited-text);margin-bottom:8px">
          ⚠ Status: needs_manual_review
        </div>
        <p class="field-value" style="margin-bottom:10px">
          Both Gemini API attempts returned invalid JSON.
          Raw response is preserved below for human review.
        </p>
        <pre class="evidence-block">${esc(diag.raw_response || '(empty)')}</pre>
      </div>`;
    return;
  }

  const pd = diag.parsed_diagnosis || {};
  const conf = typeof pd.confidence === 'number' ? pd.confidence : 0;
  const confPct = Math.round(conf * 100);
  const confCol = confPct >= 70 ? 'var(--accepted-text)' : confPct >= 40 ? 'var(--edited-text)' : 'var(--rejected-text)';

  const evidenceList = Array.isArray(pd.evidence)
    ? pd.evidence.map(e => `<li>${esc(e)}</li>`).join('')
    : `<li>${esc(pd.evidence)}</li>`;

  const fixList = Array.isArray(pd.fix_steps)
    ? pd.fix_steps.map((s, i) => `<li><strong style="color:var(--accent)">${i + 1}.</strong> ${esc(s)}</li>`).join('')
    : `<li>${esc(pd.fix_steps)}</li>`;

  el.innerHTML = `
    <div>
      <div class="field-label">Root Cause</div>
      <div class="diag-root-cause" style="margin-top:6px">${esc(pd.root_cause)}</div>
    </div>

    <div class="info-grid">
      <div class="info-field">
        <div class="field-label">Confidence</div>
        <div class="field-value" style="color:${confCol};font-weight:700;font-size:22px;margin-top:2px">${confPct}%</div>
        <div class="confidence-bar">
          <div class="confidence-fill" style="width:${confPct}%;background:${confCol}"></div>
        </div>
      </div>
      <div class="info-field">
        <div class="field-label">OSI Layer</div>
        <div class="field-value" style="margin-top:4px">${esc(pd.osi_layer)}</div>
      </div>
    </div>

    <div>
      <div class="field-label" style="margin-bottom:8px">Supporting Evidence (from AI)</div>
      <ul class="list-plain">${evidenceList || '<li style="color:var(--text-muted)">No evidence listed.</li>'}</ul>
    </div>

    <div>
      <div class="field-label">Recommended Next Command</div>
      <pre class="evidence-block" style="max-height:80px;margin-top:6px">${esc(pd.next_command || '—')}</pre>
    </div>

    <div>
      <div class="field-label" style="margin-bottom:8px">Fix Steps</div>
      <ul class="list-plain">${fixList || '<li style="color:var(--text-muted)">No fix steps listed.</li>'}</ul>
    </div>

    <div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:2px">
      <span class="meta-pill">prompt: ${esc(diag.prompt_version)}</span>
      <span class="meta-pill">model: ${esc(diag.model)}</span>
    </div>`;
}

/* ── Tab: Human Review ───────────────────────────────────────────────────── */
function renderReviewTab(review) {
  const el = $('review-content');

  if (!review) {
    el.innerHTML = `<div class="empty-state">
      <div class="empty-icon">👤</div>
      <h3>No review record</h3>
      <p>No human review entry is available for this case in <code>review_log.csv</code>.</p>
    </div>`;
    return;
  }

  const dec = review.decision || '';
  const decLower = dec.toLowerCase();
  const corr = review.corrected_fields?.trim() || null;

  const corrPills = corr
    ? corr.split(',').map(f =>
      `<span class="meta-pill" style="color:var(--edited-text)">${esc(f.trim())}</span>`
    ).join('')
    : null;

  el.innerHTML = `
    <div class="review-card">
      <div class="review-header">
        <div>
          <div class="field-label">Human Review Decision</div>
          <div style="margin-top:7px">${decisionBadge(dec)}</div>
        </div>
        <div style="text-align:right">
          <div class="field-label">Reviewer</div>
          <div class="field-value" style="margin-top:4px">${esc(review.reviewer)}</div>
        </div>
      </div>

      ${corrPills ? `
      <div style="margin-bottom:14px">
        <div class="field-label">Corrected Fields</div>
        <div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:7px">${corrPills}</div>
      </div>` : ''}

      <div>
        <div class="field-label">Reviewer Reason</div>
        <div class="info-box" style="margin-top:6px">
          ${review.reason?.trim()
      ? esc(review.reason)
      : '<em style="color:var(--text-muted)">No reason recorded (case accepted without comment).</em>'}
        </div>
      </div>
    </div>

    <div class="section-block">
      <div class="section-title">What this means</div>
      ${decLower === 'accepted'
      ? '<p style="font-size:12px;color:var(--text-secondary)">The AI diagnosis was reviewed and accepted as-is. No field corrections were required.</p>'
      : ''}
      ${decLower === 'edited'
      ? `<p style="font-size:12px;color:var(--text-secondary)">The reviewer found the AI diagnosis partially correct but requiring field-level corrections. The fields listed above were manually corrected. This demonstrates human oversight — the AI output was not blindly trusted.</p>`
      : ''}
      ${decLower === 'rejected'
      ? `<p style="font-size:12px;color:var(--rejected-text)">The AI diagnosis was substantially wrong and was rejected entirely. A correct diagnosis was recorded in <code>docs/responsible_ai_log.md</code>. This is an important responsible-AI data point.</p>`
      : ''}
    </div>`;
}

/* ══════════════════════════════════════════════════════════════════════════
   VIEW 3 — HUMAN REVIEW (full table)
══════════════════════════════════════════════════════════════════════════ */
function renderHumanReview() {
  const dash = D.dashboard;
  const dec = dash.review_decisions || {};

  /* Summary metrics */
  $('review-summary-cards').innerHTML = `
    <div class="metric-card">
      <div class="metric-label">Accepted</div>
      <div class="metric-value green">${dec.Accepted ?? 0}</div>
      <div class="metric-sub">AI diagnosis correct</div>
    </div>
    <div class="metric-card">
      <div class="metric-label">Edited</div>
      <div class="metric-value amber">${dec.Edited ?? 0}</div>
      <div class="metric-sub">Fields corrected</div>
    </div>
    <div class="metric-card">
      <div class="metric-label">Rejected</div>
      <div class="metric-value red">${dec.Rejected ?? 0}</div>
      <div class="metric-sub">Diagnosis wrong</div>
    </div>`;

  const caseMap = {};
  D.cases.forEach(c => { caseMap[c.case_id] = c; });

  const tbody = $('all-review-body');
  tbody.innerHTML = D.reviewLog.map(r => {
    const c = caseMap[r.case_id] || {};
    const dec = r.decision || '';
    return `
      <tr onclick="openCaseInExplorer('${r.case_id}')" style="cursor:pointer" tabindex="0"
          onkeydown="if(event.key==='Enter')openCaseInExplorer('${r.case_id}')">
        <td class="mono">${esc(r.case_id)}</td>
        <td>${esc(c.category || '—')}</td>
        <td>${decisionBadge(dec)}</td>
        <td style="font-family:'JetBrains Mono',monospace;font-size:10px;color:var(--text-code)">
          ${r.corrected_fields ? esc(r.corrected_fields) : '<span style="color:var(--text-muted)">—</span>'}
        </td>
        <td>${esc(r.reviewer)}</td>
      </tr>`;
  }).join('');
}

function openCaseInExplorer(id) {
  showView('explorer');
  selectCase(id);
  setTimeout(() => {
    const el = $(`ci-${id}`);
    if (el) el.scrollIntoView({ block: 'nearest' });
  }, 80);
}

/* Banner in Human Review page showing selected case (if any) */
function updateReviewSelectedBanner() {
  const banner = $('review-selected-banner');
  if (!banner) return;
  if (!selectedCaseId) {
    banner.style.display = 'none';
    return;
  }
  const review = getReviewById(selectedCaseId);
  if (!review) {
    banner.style.display = 'none';
    return;
  }
  banner.style.display = '';
  banner.innerHTML = `
    <span style="font-size:11px;color:var(--text-muted)">Currently viewing:</span>
    <span style="font-family:'JetBrains Mono',monospace;font-size:12px;font-weight:700;color:var(--accent)">${esc(selectedCaseId)}</span>
    ${decisionBadge(review.decision)}
    <button onclick="openCaseInExplorer('${selectedCaseId}')"
            style="margin-left:auto;border:1px solid var(--accent-glow);background:var(--accent-dim);color:var(--accent);
                   border-radius:20px;padding:3px 10px;font-size:11px;cursor:pointer;font-family:'Inter',sans-serif">
      Open in Explorer →
    </button>`;
}

/* ══════════════════════════════════════════════════════════════════════════
   VIEW 4 — RESPONSIBLE AI
══════════════════════════════════════════════════════════════════════════ */
function renderResponsibleAI() {
  const interventions = D.reviewLog.filter(r => r.decision === 'Edited' || r.decision === 'Rejected');
  const accepted = D.reviewLog.filter(r => r.decision === 'Accepted').length;
  const total = D.reviewLog.length;

  $('rai-total').textContent = interventions.length;
  $('rai-accepted').textContent = accepted;
  $('rai-rate').textContent = total ? Math.round((interventions.length / total) * 100) + '%' : '—';

  const caseMap = {};
  D.cases.forEach(c => { caseMap[c.case_id] = c; });

  const tbody = $('rai-body');
  if (!interventions.length) {
    tbody.innerHTML = `<tr><td colspan="6" style="padding:18px;text-align:center;color:var(--text-muted)">
      All AI diagnoses were accepted without correction.</td></tr>`;
    return;
  }

  tbody.innerHTML = interventions.map(r => {
    const c = caseMap[r.case_id] || {};
    const diag = D.diagnoses[r.case_id];
    const aiRoot = diag?.parsed_diagnosis?.root_cause
      ? diag.parsed_diagnosis.root_cause.slice(0, 110) +
      (diag.parsed_diagnosis.root_cause.length > 110 ? '…' : '')
      : (diag?.status === 'needs_manual_review' ? '(needs_manual_review)' : '—');
    const corr = r.corrected_fields
      ? r.corrected_fields.split(',')
        .map(f => `<span class="meta-pill" style="color:var(--edited-text);margin:2px">${esc(f.trim())}</span>`)
        .join('')
      : '<span style="color:var(--text-muted)">—</span>';

    return `
      <tr onclick="openCaseInExplorer('${r.case_id}')" style="cursor:pointer" tabindex="0"
          onkeydown="if(event.key==='Enter')openCaseInExplorer('${r.case_id}')">
        <td class="mono">${esc(r.case_id)}</td>
        <td>${esc(c.category || '—')}</td>
        <td style="white-space:nowrap">${decisionBadge(r.decision)}</td>
        <td style="font-size:11px;color:var(--text-secondary)">${esc(aiRoot)}</td>
        <td style="white-space:nowrap">${corr}</td>
        <td style="font-size:11px;color:var(--text-secondary)">${esc(r.reason || '—')}</td>
      </tr>`;
  }).join('');
}

/* ══════════════════════════════════════════════════════════════════════════
   VIEW 5 — WORKFLOW
══════════════════════════════════════════════════════════════════════════ */
const WORKFLOW_STEPS = [
  {
    num_type: 'ext',
    tags: [{ cls: 'ext', label: 'External Environment' }],
    title: 'Cisco Packet Tracer Lab',
    desc: 'The engineer works in a Cisco Packet Tracer simulation. They observe a network fault — for example, a PC cannot reach its gateway, or a ping fails between subnets. NetSage-AI does not directly control Packet Tracer.',
  },
  {
    num_type: 'human',
    tags: [{ cls: 'human', label: 'Manual — Engineer' }],
    title: 'Collect Evidence',
    desc: 'The engineer runs Cisco show commands (show vlan brief, show ip interface brief, show ip route, etc.) and records the symptom, topology note, and full CLI output as a case row in data/cases.csv.',
  },
  {
    num_type: '',
    tags: [{ cls: 'auto', label: 'Automated' }],
    title: 'Deterministic Rule Checking',
    desc: 'scripts/rule_checker.py runs six regex-based checks on the show-command text: duplicate IP, wrong subnet mask, gateway mismatch, interface down, missing VLAN assignment, missing route. Each returns a Finding (triggered: true/false, detail).',
  },
  {
    num_type: '',
    tags: [{ cls: 'auto', label: 'Automated' }],
    title: 'AI Diagnosis — Google Gemini',
    desc: 'scripts/diagnose.py assembles a structured prompt (symptom + topology + evidence + rule findings) and calls the Gemini API (gemini-3.5-flash-lite, temperature=0.0, AFC disabled). The model returns a JSON diagnosis object.',
  },
  {
    num_type: '',
    tags: [{ cls: 'auto', label: 'Automated' }],
    title: 'JSON Schema Validation',
    desc: 'scripts/validate_diagnosis.py validates the response against a strict 6-field schema using jsonschema (root_cause, confidence, osi_layer, evidence, next_command, fix_steps). If invalid, one retry is attempted. If both fail: status = needs_manual_review.',
  },
  {
    num_type: 'human',
    tags: [{ cls: 'human', label: 'Human — Reviewer' }],
    title: 'Human Review',
    desc: 'A human expert reviews every AI diagnosis and records Accept / Edit / Reject in data/review_log.csv, along with corrected fields and a reason. Cases with substantial errors are documented in docs/responsible_ai_log.md.',
  },
  {
    num_type: '',
    tags: [{ cls: 'auto', label: 'Automated' }],
    title: 'Dashboard & Metrics',
    desc: 'scripts/build_dashboard.py aggregates all review results and generates agreement_rate, correction_rate, and issue-type distribution charts. This presentation UI loads those metrics from dashboard/dashboard_data.json via build_data_bridge.py.',
  },
  {
    num_type: 'ext',
    tags: [{ cls: 'ext', label: 'External Environment' }],
    title: 'Engineer Applies & Verifies Fix in Packet Tracer',
    desc: 'The engineer takes the recommended fix commands (from fix_steps) back to the Cisco Packet Tracer lab and applies them. They verify the fault is resolved (e.g., ping now succeeds). NetSage does not directly control Packet Tracer — it advises; the engineer acts.',
  },
];

function renderWorkflow() {
  const container = $('workflow-steps');
  container.innerHTML = WORKFLOW_STEPS.map((step, i) => {
    const numClass = step.num_type ? ` ${step.num_type}` : '';
    const tags = step.tags.map(t => `<span class="wf-tag ${t.cls}">${t.label}</span>`).join('');
    const connector = i < WORKFLOW_STEPS.length - 1 ? '<div class="wf-connector"></div>' : '';
    return `
      <div class="wf-step">
        <div class="wf-left">
          <div class="wf-num${numClass}">${i + 1}</div>
          ${connector}
        </div>
        <div class="wf-body">
          <div class="wf-body-tags">${tags}</div>
          <div class="wf-title">${esc(step.title)}</div>
          <div class="wf-desc">${esc(step.desc)}</div>
        </div>
      </div>`;
  }).join('');
}

